import os,json,re
from pathlib import Path
checks=['/etc/lowcost-europa','/root/project-secrets/lowcost-europa','/srv/lowcost-europa']
scope=['/srv/projects/lowcost-europa','/etc/systemd/system','/etc/nginx','/etc/cron.d','/usr/local/sbin','/usr/local/bin','/root/project-secrets/restore-project-secrets.sh']
exclude={'.git','.venv','node_modules','.cache','backups','data','private','archive','staticfiles','__pycache__','.pnpm-store'}
out={'references':[],'scanned_files':0,'scanned_dirs':0,'alias_types':{},'complete':True}
for path in checks:
 p=Path(path)
 out['alias_types'][path]='symlink' if p.is_symlink() else 'directory' if p.is_dir() else 'file' if p.is_file() else 'absent'
for base in scope:
 b=Path(base)
 if b.is_file():files=[b]
 elif b.is_dir():
  files=[]
  for c,dirs,fs in os.walk(b,followlinks=False):
   out['scanned_dirs']+=1
   if out['scanned_dirs']>9000:out['complete']=False;break
   depth=len(Path(c).relative_to(b).parts)
   if depth>8:dirs[:]=[];continue
   dirs[:]=[d for d in dirs if d not in exclude]
   for f in fs:
    q=Path(c)/f
    if q.suffix in ('.py','.sh','.service','.timer','.conf','.json','.yaml','.yml','.md','.txt','') and len(files)<30000:files.append(q)
 else:continue
 for f in files:
  try:
   if not f.is_file() or f.stat().st_size>300000:continue
   content=f.read_text(errors='replace')
   out['scanned_files']+=1
   hits=[key for key in checks if key in content]
   if hits:out['references'].append({'file':str(f),'aliases':hits})
  except Exception:pass
print(json.dumps(out,separators=(',',':')))
